-- Report:  RPT_078_PO Average Days Due
-- Module:  Other
-- Source:  RPT_078_PO Average Days Due.dva
-- Generated by MFCS DVA SQL Extractor


-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT oh.order_no,oh.SUPPLIER, s.SUP_NAME, oh.LOCATION, oh.DEPT, d.DEPT_NAME,     COUNT(DISTINCT oh.ORDER_NO) AS total_pos,     ROUND(AVG(oh.NOT_AFTER_DATE - oh.WRITTEN_DATE),1) AS avg_days_to_due,     ROUND(AVG(sh.RECEIVE_DATE - oh.WRITTEN_DATE),1) AS avg_days_to_receive FROM MFCS_RDS.RDS_WV_ORDHEAD oh     JOIN MFCS_RDS.RDS_WV_SUPS s ON oh.SUPPLIER = s.SUPPLIER     LEFT JOIN MFCS_RDS.RDS_WV_DEPS d ON oh.DEPT = d.DEPT     LEFT JOIN MFCS_RDS.RDS_WV_SHIPMENT sh ON oh.ORDER_NO = sh.ORDER_NO WHERE oh.STATUS IN ('A','C') AND oh.WRITTEN_DATE &gt;= ADD_MONTHS(SYSDATE,-12) GROUP BY oh.order_no,oh.SUPPLIER, s.SUP_NAME, oh.LOCATION, oh.DEPT, d.DEPT_NAME ORDER BY avg_days_to_receive DESC NULLS LAST</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>ORDER_NO</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>SUPPLIER</ds:name><ds:datatype>varchar(4000)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>SUP_NAME</ds:name><ds:datatype>varchar(240)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>LOCATION</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>DEPT</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>DEPT_NAME</ds:name><ds:datatype>varchar(120)</ds:datatype></ds:column><ds:column><ds:name>TOTAL_POS</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>AVG_DAYS_TO_DUE</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>AVG_DAYS_TO_RECEIVE</ds:name><ds:datatype>number</ds:datatype></ds:column></ds:columns></ds:table></ds:tables><ds:prepareTables><ds:table name=\"Data\" transformed=\"true\"><ds:columns><ds:column><ds:name>ORDER_NO</ds:name></ds:column><ds:column><ds:name>SUPPLIER</ds:name></ds:column><ds:column><ds:name>SUP_NAME</ds:name></ds:column><ds:column><ds:name>LOCATION</ds:name></ds:column><ds:column><ds:n